#include <stdint.h>
#include <stdio.h>
#include <hb.h>
#include <hb-ot.h>

static void probe(hb_font_t *font, const char *label, const uint32_t *text, int size) {
    hb_buffer_t *buffer = hb_buffer_create();
    hb_buffer_set_flags(buffer, HB_BUFFER_FLAG_REMOVE_DEFAULT_IGNORABLES);
    hb_buffer_add_codepoints(buffer, text, size, 0, size);
    hb_buffer_guess_segment_properties(buffer);
    hb_shape(font, buffer, NULL, 0);

    unsigned count = 0;
    hb_glyph_info_t *glyphs = hb_buffer_get_glyph_infos(buffer, &count);
    printf("%s (%u glyphs):", label, count);
    for (unsigned i = 0; i < count; i++) {
        hb_blob_t *png = hb_ot_color_glyph_reference_png(font, glyphs[i].codepoint);
        unsigned byte_count = hb_blob_get_length(png);
        printf(" %u/cluster %u/png %u", glyphs[i].codepoint, glyphs[i].cluster, byte_count);
        if (count == 1 && glyphs[i].codepoint == 2924) {
            FILE *out = fopen(".cache/unicode/bookworm-horizontal.png", "wb");
            if (out) {
                fwrite(hb_blob_get_data(png, NULL), 1, byte_count, out);
                fclose(out);
            }
        }
        hb_blob_destroy(png);
    }
    putchar('\n');
    hb_buffer_destroy(buffer);
}

int main(int argc, char **argv) {
    const uint32_t exact[] = {0x1F642, 0x200D, 0x2194, 0xFE0F};
    const uint32_t no_joiner[] = {0x1F642, 0x2194, 0xFE0F};
    const uint32_t vertical[] = {0x1F642, 0x200D, 0x2195, 0xFE0F};
    printf("HarfBuzz %s\n", hb_version_string());
    for (int i = 1; i < argc; i++) {
        hb_blob_t *file = hb_blob_create_from_file_or_fail(argv[i]);
        if (!file) return 2;
        hb_face_t *face = hb_face_create(file, 0);
        hb_font_t *font = hb_font_create(face);
        hb_ot_font_set_funcs(font);
        hb_font_set_ppem(font, 109, 109);
        puts(argv[i]);
        probe(font, "full horizontal", exact, 4);
        probe(font, "minus VS16", exact, 3);
        probe(font, "minus ZWJ", no_joiner, 3);
        probe(font, "full vertical", vertical, 4);
        probe(font, "ordinary smile", exact, 1);
        hb_font_destroy(font);
        hb_face_destroy(face);
        hb_blob_destroy(file);
    }
    return 0;
}
